import json
import sys

operationRaw = sys.argv[1]
targetTypeRaw = sys.argv[2]
organizationRaw = sys.argv[3]
deviceNameRaw = sys.argv[4]
powerStateRaw = sys.argv[5]
slotText = sys.argv[6]
evacuationText = sys.argv[7]
forceText = sys.argv[8]
confirmText = sys.argv[9]

operation = sys.argv[10]
targetType = sys.argv[11]
organizationName = sys.argv[12]
deviceName = sys.argv[13]
powerState = sys.argv[14]
errors = []
if operationRaw != operation or targetTypeRaw != targetType or powerStateRaw != powerState:
    errors.append("Operation, Target Type, and Power State must use exact values without surrounding whitespace.")

def parse_bool(value, label):
    if value in ("true", "1"):
        return True
    if value in ("false", "0"):
        return False
    errors.append(label + " must be a boolean value.")
    return False

enableFabricEvacuation = parse_bool(evacuationText, "Enable Fabric Evacuation")
forceFabricReboot = parse_bool(forceText, "Force Fabric Reboot")
confirmForceFabricReboot = parse_bool(confirmText, "Confirm Force Fabric Reboot")

try:
    slotOrModuleId = int(slotText)
except Exception:
    slotOrModuleId = -1
    errors.append("Slot or Module ID must be an integer.")

if organizationRaw != organizationName or deviceNameRaw != deviceName:
    errors.append("Device Organization and Device Name must not contain leading or trailing whitespace.")
if not organizationName or len(organizationName) > 64 or any(ord(ch) < 32 or ch in "&?#%" for ch in organizationName):
    errors.append("Device Organization must contain 1-64 characters and must not contain control or URL query-delimiter characters.")
if not deviceName or len(deviceName) > 128 or any(ord(ch) < 32 or ch in "&?#%" for ch in deviceName):
    errors.append("Device Name must contain 1-128 characters and must not contain control or URL query-delimiter characters.")

allowedOperations = {"Set server power state", "Power cycle target"}
allowedTargets = {"Server", "CIMC", "Chassis Slot", "IFM", "Peer IFM", "Fabric Interconnect", "Unified Edge Slot"}
allowedPowerStates = {"PowerOn", "PowerOff", "PowerCycle", "HardReset", "Shutdown"}
if operation not in allowedOperations:
    errors.append("Operation must be exactly Set server power state or Power cycle target.")
if targetType not in allowedTargets:
    errors.append("Target Type is not one of the seven supported values.")

slotTargets = {"Chassis Slot", "Unified Edge Slot", "IFM", "Peer IFM"}
if operation == "Set server power state":
    if targetType != "Server":
        errors.append("Set server power state requires Target Type Server.")
    if powerState not in allowedPowerStates:
        errors.append("Power State is required and must be PowerOn, PowerOff, PowerCycle, HardReset, or Shutdown.")
else:
    if powerState:
        errors.append("Power State must be empty for Power cycle target because the workflow derives the command.")
if targetType in slotTargets:
    if not (1 <= slotOrModuleId <= 9223372036854775807):
        errors.append("Slot or Module ID must be a positive signed 64-bit integer for slot and IFM targets.")
elif slotOrModuleId != 0:
    errors.append("Slot or Module ID must remain 0 for Server, CIMC, and Fabric Interconnect targets.")

if targetType == "Fabric Interconnect":
    if forceFabricReboot and not confirmForceFabricReboot:
        errors.append("Confirm Force Fabric Reboot must be true when Force Fabric Reboot is true.")
    if not forceFabricReboot and confirmForceFabricReboot:
        errors.append("Confirm Force Fabric Reboot must remain false when Force Fabric Reboot is false.")
else:
    if not enableFabricEvacuation:
        errors.append("Enable Fabric Evacuation applies only to Fabric Interconnect and must retain its true default for other targets.")
    if forceFabricReboot or confirmForceFabricReboot:
        errors.append("Fabric force and confirmation inputs apply only to Fabric Interconnect and must remain false for other targets.")

escapedOrganizationName = sys.argv[15]
escapedDeviceName = sys.argv[16]
primaryCollection = ""
primaryNameField = ""
primarySelectSuffix = ""
secondaryKind = ""
effectivePowerState = ""
ioCommandField = ""
resetAction = ""

if targetType in ("Server", "CIMC"):
    primaryCollection = "/api/v1/compute/ServerSettings"
    primaryNameField = "Name"
    primarySelectSuffix = "&$select=Moid,Name,ObjectType,ClassId,PermissionResources,Server"
    secondaryKind = "direct"
    if targetType == "Server":
        effectivePowerState = powerState if operation == "Set server power state" else "PowerCycle"
    else:
        effectivePowerState = "Reboot"
elif targetType in ("Chassis Slot", "Unified Edge Slot", "IFM", "Peer IFM"):
    primaryCollection = "/api/v1/equipment/Chasses"
    primaryNameField = "Name"
    primarySelectSuffix = "&$select=Moid,Name,Model,PlatformType,ObjectType,ClassId,PermissionResources"
    secondaryKind = "chassis-operation" if targetType in ("Chassis Slot", "Unified Edge Slot") else "io-operation"
    if targetType == "IFM":
        ioCommandField = "AdminPowerState"
    elif targetType == "Peer IFM":
        ioCommandField = "AdminPeerPowerState"
elif targetType == "Fabric Interconnect":
    primaryCollection = "/api/v1/equipment/SwitchOperations"
    primaryNameField = "SwitchName"
    primarySelectSuffix = "&$select=Moid,SwitchName,ObjectType,ClassId,PermissionResources,NetworkElement&$expand=NetworkElement($select=Moid,ObjectType,ClassId,SwitchType)"
    secondaryKind = "direct"
    resetAction = "ForceReboot" if forceFabricReboot else "Reboot"

preparationStatus = "invalid" if errors else "ready"
preparationMessage = " ".join(errors) if errors else "Inputs, strict cross-field routing, OData values, and mutation intent were validated."
preparationResultJson = json.dumps({
    "validated": not errors,
    "errors": errors,
    "operation": operation,
    "targetType": targetType,
    "deviceOrganization": organizationName,
    "deviceName": deviceName,
    "slotOrModuleId": slotOrModuleId if targetType in slotTargets else None,
    "effectivePowerState": effectivePowerState or None,
    "resetAction": resetAction or None,
    "enableFabricEvacuation": enableFabricEvacuation if targetType == "Fabric Interconnect" else None,
    "forceFabricReboot": forceFabricReboot if targetType == "Fabric Interconnect" else None,
    "acceptedMutationOnly": True,
    "unifiedEdgeSlotTenantValidationRequired": targetType == "Unified Edge Slot"
}, separators=(",", ":"))
helperReady = preparationStatus in ("invalid", "ready") and bool(preparationMessage and preparationResultJson) and (preparationStatus != "ready" or bool(primaryCollection and primaryNameField and primarySelectSuffix and secondaryKind))

import json
import re
import sys

# HTTP evidence is independent from strict organization identity inspection.
# The connector contract supplies an integral HTTP status and Boolean success.
try:
    httpStatus = int(sys.argv[4])
except (ValueError, TypeError):
    httpStatus = 0
requestSucceeded = sys.argv[5].strip().lower() == "true"
if not requestSucceeded or httpStatus != 200:
    statusCode = httpStatus if 300 <= httpStatus < 600 else 502
    lookupStatus = "api-failure"
    message = "Organization lookup API request failed"
    errorMessage = "The organization request failed or returned a non-200 response."
    organizationMoid, organizationJson, inspectionComplete = "", "{}", False
    safeCode, safeMessage = "", ""
    try:
        payload = json.loads(sys.argv[1])
        # Preserve the native String projection used by the old safe allowlists.
        def text(value):
            return value if isinstance(value, str) else json.dumps(value, separators=(",", ":"), ensure_ascii=False)
        code = text(payload["Code"]) if isinstance(payload, dict) and "Code" in payload else ""
        detail = text(payload["Message"]) if isinstance(payload, dict) and "Message" in payload else ""
        if re.fullmatch(r"[A-Za-z0-9_.:-]{1,128}", code):
            safeCode = code
        if re.fullmatch(r"[A-Za-z0-9 _.,:()/+\-]{1,500}", detail) and not re.search(r"authorization|password|secret|token|api.?key|bearer|https?://", detail, re.IGNORECASE):
            safeMessage = detail
    except Exception:
        pass
    if safeMessage:
        errorMessage = safeMessage
    resultJson = json.dumps({"status":"api-failure", "upstreamStatus":httpStatus, "Code":safeCode, "Message":safeMessage}, separators=(",", ":"))
else:
    import json
    import re
    import sys
    statusCode, lookupStatus, message = 502, "invalid-response", "Organization response is invalid"
    organizationMoid, organizationJson = "", "{}"
    inspectionComplete = False
    try:
        payload = json.loads(sys.argv[1])
        if not isinstance(payload, dict): raise ValueError("Organization response must be an object")
        count, rows = payload.get("Count"), payload.get("Results")
        if isinstance(count, bool) or not isinstance(count, int) or count < 0: raise ValueError("Count must be a nonnegative integer")
        if not isinstance(rows, list): raise ValueError("Results must be an array")
        if count != len(rows): raise ValueError("Count and Results length differ; the bounded page is incomplete")
        if count > 2: raise ValueError("Count exceeds the two-row lookup bound")
        if count == 0: statusCode, lookupStatus, message = 404, "not-found", "No organization matched the exact requested name"
        elif count != 1: statusCode, lookupStatus, message = 409, "ambiguous", "More than one organization matched the exact requested name"
        else:
            item = rows[0]
            if not isinstance(item, dict) or item.get("Name") != sys.argv[2]: raise ValueError("Organization Name does not match exactly")
            if item.get("ObjectType") != "organization.Organization" or item.get("ClassId") != "organization.Organization": raise ValueError("Organization discriminators do not match")
            moid = item.get("Moid")
            pattern = r"[0-9a-fA-F]{24}" if sys.argv[3] == "Hex24" else r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}"
            if not isinstance(moid, str) or re.fullmatch(pattern, moid) is None: raise ValueError("Organization Moid is missing or malformed")
            organizationMoid = moid
            projected = {key:item[key] for key in ("Moid", "Name", "ObjectType", "ClassId")}
            organizationJson = json.dumps(projected, separators=(",", ":"))
            resultJson = json.dumps({"Count":1,"Results":[projected]}, separators=(",", ":"))
            statusCode, lookupStatus, message = 200, "exact", "Organization resolved exactly"
        inspectionComplete = True
    except Exception as exc:
        statusCode, lookupStatus, message, inspectionComplete = 502, "invalid-response", str(exc), True
    errorMessage = "" if statusCode == 200 else message
    if statusCode != 200: resultJson = json.dumps({"status":lookupStatus,"error":message}, separators=(",", ":"))

import json
import re
import sys
payload = json.loads(sys.argv[1])
targetType = sys.argv[2]
expectedName = sys.argv[3]
organizationMoid = sys.argv[4]
values = payload.get("Results")
if not isinstance(values, list):
    raise ValueError("Primary target response is missing a Results array")

def safe_moid(value):
    return isinstance(value, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}", value) is not None

def relationship_matches(rel, moid, object_types):
    return isinstance(rel, dict) and rel.get("Moid") == moid and rel.get("ObjectType") in object_types and rel.get("ClassId") in (None, "mo.MoRef", rel.get("ObjectType"))

def permission_matches(items):
    if not isinstance(items, list):
        return False
    matches = [r for r in items if relationship_matches(r, organizationMoid, {"organization.Organization"})]
    return len(matches) == 1

primaryMoid = ""
primaryObjectType = ""
if len(values) == 0:
    primaryStatus = "not-found"
    primaryMessage = "No exact primary power target matched name, organization, and route."
elif len(values) > 1:
    primaryStatus = "ambiguous"
    primaryMessage = "Multiple primary power targets matched the exact lookup."
else:
    item = values[0]
    problems = []
    if targetType in ("Server", "CIMC"):
        expectedType = "compute.ServerSetting"
        nameField = "Name"
    elif targetType == "Fabric Interconnect":
        expectedType = "equipment.SwitchOperation"
        nameField = "SwitchName"
    else:
        expectedType = "equipment.Chassis"
        nameField = "Name"
    if not isinstance(item, dict):
        problems.append("Primary result is not an object.")
    else:
        moid = str(item.get("Moid") or "")
        if not safe_moid(moid):
            problems.append("Primary result Moid is missing or not URL-safe.")
        if item.get(nameField) != expectedName:
            problems.append("Primary result name does not exactly match Device Name.")
        if item.get("ObjectType") != expectedType or item.get("ClassId") != expectedType:
            problems.append("Primary result discriminators do not match the routed schema.")
        if not permission_matches(item.get("PermissionResources")):
            problems.append("Primary result does not contain exactly one matching organization permission relationship.")
        if targetType in ("Server", "CIMC"):
            server = item.get("Server")
            if not isinstance(server, dict) or not safe_moid(str(server.get("Moid") or "")) or server.get("ObjectType") not in ("compute.Blade", "compute.RackUnit") or server.get("ClassId") not in (None, "mo.MoRef", server.get("ObjectType")):
                problems.append("ServerSetting.Server must identify one concrete Blade or RackUnit.")
        elif targetType == "Fabric Interconnect":
            element = item.get("NetworkElement")
            if not isinstance(element, dict) or not safe_moid(str(element.get("Moid") or "")) or element.get("ObjectType") != "network.Element" or element.get("ClassId") not in (None, "mo.MoRef", "network.Element") or element.get("SwitchType") != "FabricInterconnect":
                problems.append("SwitchOperation.NetworkElement must be an expanded FabricInterconnect relationship.")
        elif targetType == "Unified Edge Slot":
            model = str(item.get("Model") or "")
            if not model.startswith("UCSXE-"):
                problems.append("Unified Edge Slot requires a chassis model beginning with UCSXE-.")
    if problems:
        primaryStatus = "invalid"
        primaryMessage = " ".join(problems)
    else:
        primaryStatus = "exact"
        primaryMoid = item["Moid"]
        primaryObjectType = expectedType
        primaryMessage = "Exactly one primary target and all required relationships were validated."
primaryResultJson = json.dumps({"status": primaryStatus, "message": primaryMessage, "targetType": targetType, "primaryMoid": primaryMoid or None, "primaryObjectType": primaryObjectType or None}, separators=(",", ":"))
helperReady = primaryStatus in ("not-found", "ambiguous", "invalid", "exact") and bool(primaryMessage and primaryResultJson) and (primaryStatus != "exact" or bool(primaryMoid and primaryObjectType))

import json
import re
import sys
targetType = sys.argv[1]
effectivePowerState = sys.argv[2]
ioCommandField = sys.argv[3]
resetAction = sys.argv[4]
slotOrModuleId = int(sys.argv[5])
enableFabricEvacuation = sys.argv[10] in ('true', '1')
operationMoid = sys.argv[7]
primaryResolution = json.loads(sys.argv[8])
operationResolution = json.loads(sys.argv[9])
if not re.fullmatch('[A-Za-z0-9][A-Za-z0-9._~-]{0,127}', operationMoid):
    raise ValueError('Resolved operation Moid is missing or not URL-safe')
if not isinstance(primaryResolution, dict) or primaryResolution.get('status') != 'exact':
    raise ValueError('Stored primary resolution is not exact')
if not isinstance(operationResolution, dict) or operationResolution.get('status') != 'exact':
    raise ValueError('Stored operation resolution is not exact')
if targetType in ('Server', 'CIMC'):
    expectedObjectType = 'compute.ServerSetting'
    mutationUrl = '/api/v1/compute/ServerSettings/' + operationMoid
    request = {'ClassId': expectedObjectType, 'ObjectType': expectedObjectType, 'AdminPowerState': effectivePowerState}
elif targetType == 'Chassis Slot':
    expectedObjectType = 'equipment.ChassisOperation'
    mutationUrl = '/api/v1/equipment/ChassisOperations/' + operationMoid
    request = {'ClassId': expectedObjectType, 'ObjectType': expectedObjectType, 'AdminPowerCycleSlotId': slotOrModuleId}
elif targetType in ('IFM', 'Peer IFM'):
    expectedObjectType = 'equipment.IoCardOperation'
    mutationUrl = '/api/v1/equipment/IoCardOperations/' + operationMoid
    if ioCommandField not in ('AdminPowerState', 'AdminPeerPowerState'):
        raise ValueError('IFM command field is invalid')
    request = {'ClassId': expectedObjectType, 'ObjectType': expectedObjectType, ioCommandField: 'Reboot'}
elif targetType == 'Fabric Interconnect':
    expectedObjectType = 'equipment.SwitchOperation'
    mutationUrl = '/api/v1/equipment/SwitchOperations/' + operationMoid
    if resetAction not in ('Reboot', 'ForceReboot'):
        raise ValueError('Fabric Interconnect ResetAction is invalid')
    request = {'ClassId': expectedObjectType, 'ObjectType': expectedObjectType, 'ResetAction': {'ClassId': 'equipment.ResetAction', 'ObjectType': 'equipment.ResetAction', 'Action': resetAction, 'EnableFabricEvacuation': enableFabricEvacuation}}
else:
    raise ValueError('Target Type has no mutation route')
mutationBodyJson = json.dumps(request, separators=(',', ':'))
mutationIntentJson = json.dumps({'operationMoid': operationMoid, 'objectType': expectedObjectType, 'targetType': targetType, 'request': request, 'acceptedMutationOnly': True}, separators=(',', ':'))
helperReady = bool(mutationUrl and mutationBodyJson and mutationIntentJson and expectedObjectType)
